package main

import (
	"fmt"
)

type ValidationError struct {
	Field string
	Value interface{}
	Msg   string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("validation failed: %s = %v - %s", e.Field, e.Value, e.Msg)
}

func validateAge(age int) error {
	if age < 0 {
		return &ValidationError{"age", age, "must be non-negative"}
	}
	if age > 150 {
		return &ValidationError{"age", age, "must be <= 150"}
	}
	return nil
}

func main() {
	err := validateAge(-5)
	if err != nil {
		fmt.Println(err)
	}

	err = validateAge(200)
	if err != nil {
		fmt.Println(err)
	}

	fmt.Println("All validations complete")
}
